package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.repository.jobs.ProcessApiRuntimeTelemetry;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.time.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.runner.ApplicationContextRunner;import org.springframework.mock.web.*;import org.springframework.web.method.HandlerMethod;import org.springframework.web.servlet.HandlerMapping;
class ApiRuntimeInstrumentationConfigurationTest {
 static final Instant START=Instant.parse("2026-01-01T00:05:00Z");static final class Endpoint{public void call(){}}
 static final class Fixture{final AtomicReference<Instant> at=new AtomicReference<>(START);final AtomicLong nanos=new AtomicLong();final ProcessApiRuntimeTelemetry probe=new ProcessApiRuntimeTelemetry(new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at.get();}},nanos::get,START.minusSeconds(300),"00000000-0000-4000-8000-000000000001");void completeWindow(){at.set(START.plusSeconds(300));nanos.set(300000000000L);}}
 MockHttpServletRequest mapped()throws Exception{var request=new MockHttpServletRequest("GET","/admin/fictional");request.setAttribute(HandlerMapping.BEST_MATCHING_HANDLER_ATTRIBUTE,new HandlerMethod(new Endpoint(),Endpoint.class.getMethod("call")));return request;}
 @Test void actualMappedStatusesAndUncaughtEndpointFailureCountWithoutChangingResponseOrException()throws Exception{var f=new Fixture();try(var capture=f.probe.openCapture()){var filter=new ApiRuntimeInstrumentationConfiguration.CompletionFilter(f.probe);for(int code:new int[]{200,401,503}){var response=new MockHttpServletResponse();filter.doFilter(mapped(),response,(request,result)->((HttpServletResponse)result).setStatus(code));assertEquals(code,response.getStatus());}var error=new ServletException("fictional endpoint unavailable");assertSame(error,assertThrows(ServletException.class,()->filter.doFilter(mapped(),new MockHttpServletResponse(),(request,response)->{throw error;})));filter.doFilter(new MockHttpServletRequest("GET","/fictional-unmapped"),new MockHttpServletResponse(),(request,response)->((HttpServletResponse)response).setStatus(404));f.completeWindow();var value=f.probe.read();assertEquals(4,value.requests());assertEquals(2,value.serverErrors());}}
 @Test void asyncCompletionCountsOnceInActualCompletionWindowAndKeepsAsyncResponse()throws Exception{var f=new Fixture();try(var capture=f.probe.openCapture()){var filter=new ApiRuntimeInstrumentationConfiguration.CompletionFilter(f.probe);var request=mock(HttpServletRequest.class);var response=new MockHttpServletResponse();var context=mock(AsyncContext.class);var listeners=new java.util.ArrayList<AsyncListener>();when(request.getAttribute(HandlerMapping.BEST_MATCHING_HANDLER_ATTRIBUTE)).thenReturn(new HandlerMethod(new Endpoint(),Endpoint.class.getMethod("call")));when(request.isAsyncStarted()).thenReturn(true);when(request.getAsyncContext()).thenReturn(context);doAnswer(call->{listeners.add(call.getArgument(0));return null;}).when(context).addListener(any(AsyncListener.class));filter.doFilter(request,response,(req,res)->((HttpServletResponse)res).setStatus(503));assertEquals(1,listeners.size());f.completeWindow();assertEquals(0,f.probe.read().requests());var event=new AsyncEvent(context,request,response);listeners.getFirst().onError(event);listeners.getFirst().onComplete(event);listeners.getFirst().onComplete(event);f.at.set(START.plusSeconds(600));f.nanos.set(600000000000L);assertEquals(1,f.probe.read().requests());assertEquals(1,f.probe.read().serverErrors());assertEquals(503,response.getStatus());}}
 @Test void captureLifecycleStartsOnceStopsAndRejectsDuplicateCaptureWithoutAHealthyDefault(){var f=new Fixture();var lifecycle=new ApiRuntimeInstrumentationConfiguration.NativeCapture(f.probe);assertFalse(lifecycle.isRunning());assertNull(f.probe.read());lifecycle.start();lifecycle.start();assertThrows(IllegalStateException.class,()->new ApiRuntimeInstrumentationConfiguration.NativeCapture(f.probe).start());f.completeWindow();assertNotNull(f.probe.read());var done=new AtomicBoolean();lifecycle.stop(()->done.set(true));assertTrue(done.get());assertFalse(lifecycle.isRunning());assertNull(f.probe.read());assertEquals("ApiRuntimeNativeCapture[redacted]",lifecycle.toString());}
 @Test void absentOrDisabledFlagsCreateNoCaptureOrFilterAndActualFactoryUsesNativeProcess(){for(String[] flags:new String[][]{{},{"site.ops.api-monitoring.enabled=false","site.browser.enabled=true"},{"site.ops.api-monitoring.enabled=true","site.browser.enabled=false"}})new ApplicationContextRunner().withUserConfiguration(ApiRuntimeInstrumentationConfiguration.class).withPropertyValues(flags).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(ApiRuntimeInstrumentationConfiguration.NativeCapture.class).isEmpty());assertTrue(c.getBeansOfType(org.springframework.boot.web.servlet.FilterRegistrationBean.class).isEmpty());});new ApplicationContextRunner().withUserConfiguration(ApiRuntimeInstrumentationConfiguration.class).withPropertyValues("site.ops.api-monitoring.enabled=true","site.browser.enabled=true").run(c->{assertNull(c.getStartupFailure());var value=c.getBean(ApiRuntimeInstrumentationConfiguration.NativeCapture.class);assertSame(ProcessApiRuntimeTelemetry.nativeProcess(),value.probe);assertTrue(value.isRunning());assertNull(value.probe.read());});}
}
